-- Step 1 of 5: add accounts.region as NULLABLE (replaces the draft's single
-- "ADD COLUMN region text NOT NULL", which fails on a table with rows, or with a
-- default would stamp 40M rows with an invented value).
-- Postgres: adding a nullable column with no default is a catalog-only change, no
-- table rewrite. It still needs a brief ACCESS EXCLUSIVE lock, so give up quickly
-- instead of queueing behind long transactions and blocking all writers; the
-- runner retries.
-- Reversible: yes (see down).
SET lock_timeout = '3s';

ALTER TABLE accounts ADD COLUMN IF NOT EXISTS region text;

COMMENT ON COLUMN accounts.region IS
  'Account region code. NOT NULL is enforced from step 0005 on; until then NULL means not yet backfilled.';

-- Rows the backfill cannot resolve are kept here with a reason, not dropped or guessed.
CREATE TABLE IF NOT EXISTS accounts_region_rejected (
  account_id  bigint PRIMARY KEY,
  reason      text        NOT NULL,
  seen_value  text,
  rejected_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS backfill_progress (
  job     text PRIMARY KEY,
  last_id bigint NOT NULL
);

-- Down for step 1.
-- WARNING: once the backfill (step 2) has run, dropping the column deletes the
-- region values it wrote. That cannot be undone, so a copy is kept first. Running
-- this down after the backfill is a P1: escalate and get approval before you run it.
SET lock_timeout = '3s';

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = 'accounts' AND column_name = 'region') THEN
    CREATE TABLE IF NOT EXISTS accounts_region_backup AS
      SELECT id AS account_id, region FROM accounts WHERE region IS NOT NULL;
  END IF;
END $$;

ALTER TABLE accounts DROP COLUMN IF EXISTS region;
DROP TABLE IF EXISTS backfill_progress;
-- accounts_region_rejected and accounts_region_backup are kept on purpose; drop them by hand once nobody needs them.

-- Step 5 of 5: make the column NOT NULL itself.
-- Postgres 12+ sees the validated CHECK and skips the full-table scan, so this is
-- a brief lock only. The CHECK is then redundant and is dropped.
-- Reversible: yes.
SET lock_timeout = '3s';

ALTER TABLE accounts ALTER COLUMN region SET NOT NULL;
ALTER TABLE accounts DROP CONSTRAINT IF EXISTS accounts_region_not_null;
